from mbuild import *

def signin():
    card_html = '\n'.join([
        '<div style="display: flex; flex-direction: column; gap: 4px"><h1 style="margin: 0; font-size: 22px; line-height: 28px; font-weight: 600; letter-spacing: -0.01em">Sign in</h1>'
        '<sc-if value="{{isEmail}}" hint-placeholder-val="{{true}}"><p class="mm-muted" style="margin: 0">We will email you a 6-digit code.</p></sc-if><sc-if value="{{isCode}}" hint-placeholder-val="{{false}}"><p class="mm-muted" style="margin: 0">{{sentText}}</p></sc-if></div>',
        '<sc-if value="{{hasErr}}" hint-placeholder-val="{{false}}"><div class="mm-alert mm-alert-bad" role="alert">' + svg(ICONS['alert']) + '<p style="margin: 0">{{errText}}</p></div></sc-if>',
        '<sc-if value="{{isEmail}}" hint-placeholder-val="{{true}}"><div class="mm-field"><label class="mm-label" for="mm-si-em">Email address</label><input id="mm-si-em" class="mm-input" type="email" autoComplete="email" aria-invalid="{{emailAria}}" value="{{email}}" onChange="{{onEmail}}" placeholder="you@example.com"><sc-if value="{{emailBad}}" hint-placeholder-val="{{false}}"><p class="mm-hint mm-err">Enter your email address.</p></sc-if></div>'
        '<sc-if value="{{isCheck}}" hint-placeholder-val="{{false}}"><div style="display: flex; align-items: center; gap: 10px; height: 64px; padding: 0 14px; border: 1px solid var(--border); border-radius: 8px; background: var(--muted)"><span class="mm-check" style="width: 22px; height: 22px; border-color: var(--input); background: var(--background)"></span><span>Verify you are human</span><span style="flex: 1"></span><span class="mm-muted" style="font-size: 11px">Cloudflare</span></div></sc-if>'
        '<button type="button" class="mm-btn mm-primary" style="width: 100%; height: 40px" onClick="{{send}}">Send code</button></sc-if>',
        '<sc-if value="{{isCode}}" hint-placeholder-val="{{false}}"><div class="mm-field"><label class="mm-label" for="mm-si-cd">Code from the email</label><input id="mm-si-cd" class="mm-input mm-otp" inputMode="numeric" autoComplete="one-time-code" aria-invalid="{{codeAria}}" value="{{code}}" onChange="{{onCode}}" placeholder="••••••" style="height: 48px"></div>'
        '<button type="button" class="mm-btn mm-primary" style="width: 100%; height: 40px" onClick="{{submit}}">Sign in</button>'
        '<div style="display: flex; flex-direction: column; align-items: center; gap: 4px"><sc-if value="{{waitResend}}" hint-placeholder-val="{{true}}"><p class="mm-muted" style="margin: 0; font-size: 13px">{{resendText}}</p></sc-if>'
        '<sc-if value="{{canResend}}" hint-placeholder-val="{{false}}"><button type="button" class="mm-btn mm-ghost" onClick="{{resend}}">Send a new code</button></sc-if>'
        '<button type="button" class="mm-btn mm-ghost" style="height: 32px" onClick="{{changeEmail}}">Use another email</button></div></sc-if>'])
    auth('SignIn', 'Sign in', card_html, mread('signin.js'))

def twofactor():
    card_html = '\n'.join([
        '<div style="display: flex; flex-direction: column; gap: 4px"><h1 style="margin: 0; font-size: 22px; line-height: 28px; font-weight: 600">Two-factor login</h1><p class="mm-muted" style="margin: 0">Enter the 6-digit code your authenticator app shows for managemind.</p></div>',
        '<sc-if value="{{expired}}" hint-placeholder-val="{{false}}"><div class="mm-alert mm-alert-bad" role="alert">' + svg(ICONS['clock']) + '<p style="margin: 0">This sign-in took too long. Please start again.</p></div><a href="SignIn.dc.html" class="mm-btn mm-primary" style="width: 100%; height: 40px">Sign in</a></sc-if>',
        '<sc-if value="{{notExpired}}" hint-placeholder-val="{{true}}"><div class="mm-field"><label class="mm-label" for="mm-tf-c">{{label}}</label>'
        '<sc-if value="{{app}}" hint-placeholder-val="{{true}}"><input id="mm-tf-c" class="mm-input mm-otp" inputMode="numeric" autoComplete="one-time-code" aria-invalid="{{aria}}" value="{{code}}" onChange="{{onCode}}" placeholder="••••••" style="height: 48px"></sc-if>'
        '<sc-if value="{{backup}}" hint-placeholder-val="{{false}}"><input id="mm-tf-c" class="mm-input mm-mono" autoComplete="off" aria-invalid="{{aria}}" value="{{code}}" onChange="{{onCode}}" placeholder="XXXX-XXXX" style="height: 44px; text-align: center; letter-spacing: .1em"></sc-if>'
        '<sc-if value="{{bad}}" hint-placeholder-val="{{false}}"><p class="mm-hint mm-err">That code is not right. Try again.</p></sc-if></div>'
        '<label style="display: flex; align-items: center; gap: 10px; cursor: pointer">' + checkbox('trust') + 'Trust this device for 30 days</label>'
        '<button type="button" class="mm-btn mm-primary" style="width: 100%; height: 40px" onClick="{{submit}}">Continue</button>'
        '<button type="button" class="mm-btn mm-ghost" style="align-self: center" onClick="{{toggleMode}}">{{switchText}}</button></sc-if>'])
    auth('TwoFactor', 'Two-factor login', card_html, mread('twofactor.js'))

def invite():
    card_html = '\n'.join([
        '<h1 style="margin: 0; font-size: 22px; line-height: 28px; font-weight: 600">Invitation</h1>',
        '<sc-if value="{{joining}}" hint-placeholder-val="{{true}}"><div style="display: flex; align-items: center; gap: 12px">' + svg(ICONS['refresh'], 18, 'flex: none; color: var(--muted-foreground)') + '<p style="margin: 0">Joining Nakshi Fashion…</p></div>'
        '<p class="mm-muted" style="margin: 0; font-size: 13px">Shapla Akter invited you as Staff. You’ll land on the store’s home in a moment.</p></sc-if>',
        '<sc-if value="{{invalid}}" hint-placeholder-val="{{false}}"><div class="mm-alert mm-alert-bad" role="alert">' + svg(ICONS['alert']) + '<p style="margin: 0">This invitation is no longer valid, or it was sent to another email address. Ask the store owner for a new one, or sign in with the address it was sent to.</p></div>'
        '<p class="mm-muted" style="margin: 0; font-size: 13px">Signed in as tania.s@outlook.com</p><button type="button" class="mm-btn mm-outline" style="width: 100%" onClick="{{signOut}}">Sign out</button></sc-if>',
        '<sc-if value="{{missing}}" hint-placeholder-val="{{false}}"><div class="mm-alert mm-alert-bad" role="alert">' + svg(ICONS['link']) + '<p style="margin: 0">This link is incomplete. Open the link in the invitation email again.</p></div></sc-if>'])
    auth('Invite', 'Invitation', card_html, mread('invite.js'))

def account():
    sess = ('<ul style="list-style: none; margin: 0 -20px; padding: 0"><sc-for list="{{sessions}}" as="se" hint-placeholder-count="3"><li style="display: flex; align-items: center; gap: 12px; min-height: 56px; padding: 6px 12px 6px 20px; border-top: 1px solid var(--border)">'
            + svg(ICONS['monitor'], 18, 'flex: none; color: var(--muted-foreground)') + '<span style="flex: 1; min-width: 0; display: flex; flex-direction: column"><span style="display: flex; align-items: center; gap: 6px"><span style="font-weight: 500">{{se.device}}</span><sc-if value="{{se.current}}" hint-placeholder-val="{{false}}"><span class="mm-badge-sec">This device</span></sc-if></span><span class="mm-muted" style="font-size: 13px">{{se.where}}</span></span>'
            '<sc-if value="{{se.other}}" hint-placeholder-val="{{true}}"><button type="button" class="mm-btn mm-ghost" style="height: 32px" onClick="{{se.out}}">Sign out</button></sc-if></li></sc-for></ul>'
            '<sc-if value="{{hasOthers}}" hint-placeholder-val="{{true}}"><button type="button" class="mm-btn mm-outline" style="align-self: flex-start" onClick="{{outOthers}}">Sign out everywhere else</button></sc-if>')
    qr = '<div class="mm-qr" role="img" aria-label="QR code for your authenticator app"><sc-for list="{{qr}}" as="q" hint-placeholder-count="121"><span style="background: {{q.bg}}"></span></sc-for></div>'
    tf = '\n'.join([
        '<sc-if value="{{tfOff}}" hint-placeholder-val="{{true}}"><p class="mm-muted" style="margin: 0">Off. Turn it on to ask for a code from your phone when you sign in.</p><button type="button" class="mm-btn mm-primary" style="align-self: flex-start" onClick="{{setUp}}">' + svg(ICONS['lock']) + 'Set up</button></sc-if>',
        '<sc-if value="{{tfSetup}}" hint-placeholder-val="{{false}}"><p style="margin: 0">Scan this QR code with an authenticator app, such as Google Authenticator, then enter the 6-digit code it shows.</p>'
        '<div style="display: flex; flex-wrap: wrap; align-items: center; gap: 20px">' + qr + '<div style="display: flex; flex-direction: column; gap: 6px"><span class="mm-muted" style="font-size: 13px">Can’t scan? Enter this key:</span><span class="mm-code2" style="font-size: 14px; padding: 6px 10px">{{key}}</span></div></div>'
        '<div class="mm-field" style="max-width: 240px"><label class="mm-label" for="mm-tf-s">Authenticator code</label><input id="mm-tf-s" class="mm-input mm-otp" inputMode="numeric" aria-invalid="{{taria}}" value="{{tcode}}" onChange="{{onTcode}}" placeholder="••••••"><sc-if value="{{terr}}" hint-placeholder-val="{{false}}"><p class="mm-hint mm-err">That code is not right. Try again.</p></sc-if></div>'
        '<div style="display: flex; gap: 8px"><button type="button" class="mm-btn mm-primary" onClick="{{enable}}">Turn on</button><button type="button" class="mm-btn mm-ghost" onClick="{{cancelSetup}}">Cancel</button></div></sc-if>',
        '<sc-if value="{{tfOn}}" hint-placeholder-val="{{false}}">' + statusline('Two-factor login is on', 'You’ll be asked for a code from your authenticator app when you sign in.') + '<div style="display: flex; flex-wrap: wrap; gap: 8px"><button type="button" class="mm-btn mm-outline" onClick="{{newCodes}}">New backup codes</button><button type="button" class="mm-btn mm-ghost mm-danger" onClick="{{disable}}">Turn off</button></div></sc-if>'])
    body = '\n'.join([
        card('mm-c-ap', 'Profile', '\n'.join([text('mm-ap-n', 'Name', 'name'), '<div class="mm-field"><span class="mm-label">Email</span><div class="mm-readonly">' + svg(ICONS['mail'], 16, 'flex: none; color: var(--muted-foreground)') + 'rafiq@nakshifashion.com.bd</div></div>',
             segs('mm-l-al', 'Language for the admin and emails', 'langs', 'al', 2)])),
        card('mm-c-at', 'Two-factor login', tf, gap='14px'), card('mm-c-as', 'Where you are signed in', sess, gap='8px')])
    codes = ('<p class="mm-muted" style="margin: 0">Keep these somewhere safe. If you lose your phone, each code signs you in once.</p><div style="display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px"><sc-for list="{{codes}}" as="bc" hint-placeholder-count="8"><span class="mm-code2" style="padding: 8px; text-align: center; font-size: 14px">{{bc.code}}</span></sc-for></div>')
    codes_dlg = ('<sc-if value="{{codesOpen}}" hint-placeholder-val="{{false}}"><div style="position: fixed; inset: 0; z-index: 80"><div aria-hidden="true" style="position: absolute; inset: 0; background: rgb(0 0 0 / .5)"></div>'
                 '<div role="dialog" aria-modal="true" aria-labelledby="mm-bc-t" class="mm-dialog" style="max-width: 440px; gap: 16px"><h2 id="mm-bc-t" style="margin: 0; font-size: 18px; font-weight: 600">Backup codes</h2>' + codes +
                 '<div style="display: flex; justify-content: flex-end; gap: 8px"><button type="button" class="mm-btn mm-outline" onClick="{{copyCodes}}">' + svg(ICONS['copy']) + 'Copy codes</button><button type="button" class="mm-btn mm-primary" onClick="{{doneCodes}}">I saved them</button></div></div></div></sc-if>')
    off_d = palert('dl.open', 'Turn off two-factor login?', '<p style="margin: 0">You’ll sign in with an email code only.</p>', 'closeAll', 'dl.confirm', 'Turn off')
    head = '<div style="display: flex; flex-direction: column; gap: 4px"><h1 style="margin: 0; font-size: 20px; line-height: 28px; font-weight: 600">Account</h1><p class="mm-muted" style="margin: 0">Your profile, two-factor login and where you are signed in.</p></div>'
    d = '\n'.join([MAIN, '<div style="display: flex; flex-direction: column; gap: 16px; width: 100%; max-width: 760px">', head, body.replace('@@AFFIX@@', '8px'), bar(), '</div>']) + DEND + codes_dlg + '\n' + off_d + XEND
    bp = re.sub(r'grid-template-columns: repeat\(\d, minmax\(0, 1fr\)\)', 'grid-template-columns: minmax(0, 1fr)', body)
    ph = '\n'.join([PROOT % 'var(--page)', phone_back('Phone.dc.html', 'Back to menu', 'Account'), '<main class="mm-scroll" style="gap: 12px; padding: 12px">', bp, '</main>', pbar()])
    ph += '\n' + pdrawer('codesOpen', 'doneCodes', 'mm-bc-t', 'Backup codes', '', pbody(codes), '<div style="flex: none; display: flex; gap: 8px; padding: 12px 16px; border-top: 1px solid var(--border)"><button type="button" class="mm-btn mm-outline" style="flex: 1" onClick="{{copyCodes}}">Copy codes</button><button type="button" class="mm-btn mm-primary" style="flex: 1" onClick="{{doneCodes}}">I saved them</button></div>', tall=False)
    ph += '\n' + phalert('dl.open', 'Turn off two-factor login?', '<p style="margin: 0">You’ll sign in with an email code only.</p>', 'closeAll', 'dl.confirm', 'Turn off') + '\n@@PTOAST0@@\n\n</div>\n</x-dc>\n'
    js = mread('account.js'); opts = js_starts(js); jsall = RSHARED + sread('shared.js') + js
    write('Account', shell_head('Account', [('Account', '')]), rexpand(d), jsall, props(opts, opts[0]), 'mm mm-root')
    write('AccountPhone', sphead('Account'), expand(ph, True), jsall, props(opts, opts[0], True), 'mm')

def printdocs():
    qr = '<div class="mm-qr" role="img" aria-label="QR code for order {{dc.n}}"><sc-for list="{{qrc}}" as="q" hint-placeholder-count="121"><span style="background: {{q.bg}}"></span></sc-for></div>'
    invoice = ('<article class="mm-paper"><div style="display: flex; justify-content: space-between; gap: 24px"><div style="display: flex; flex-direction: column; gap: 2px"><span style="font-size: 18px; font-weight: 700">Nakshi Fashion House</span><span>House 18, Road 7, Block C, Mirpur 10, Dhaka</span><span>01712-345678 · hello@nakshifashion.com.bd</span><span style="color: #555">Trade licence: TRAD/DNCC/045218/2024</span></div>'
               '<div style="display: flex; flex-direction: column; align-items: flex-end; gap: 2px; text-align: right"><span style="font-size: 20px; font-weight: 700">{{T.invoice}}</span><span>{{T.no}} {{dc.n}}</span><span>{{dc.date}}</span><span style="font-weight: 600">{{dc.status}}</span></div></div>'
               '<div style="margin: 28px 0 20px"><p style="margin: 0 0 4px; font-weight: 600">{{T.billTo}}</p><p style="margin: 0">{{dc.name}} · {{dc.phone}}</p><p style="margin: 0; color: #444">{{dc.address}}</p></div>'
               '<table><thead><tr><th>{{T.item}}</th><th class="r">{{T.qty}}</th><th class="r">{{T.unit}}</th><th class="r">{{T.amount}}</th></tr></thead><tbody><sc-for list="{{dc.lines}}" as="ln" hint-placeholder-count="2"><tr><td>{{ln.name}}<br><span style="color: #666; font-size: 11px">{{ln.sku}}</span></td><td class="r">{{ln.qty}}</td><td class="r">{{ln.unit}}</td><td class="r">{{ln.amount}}</td></tr></sc-for></tbody></table>'
               '<dl style="margin: 16px 0 0 auto; width: 300px; display: flex; flex-direction: column; gap: 4px"><sc-for list="{{dc.sums}}" as="sm" hint-placeholder-count="3"><div style="display: flex; justify-content: space-between"><dt>{{sm.label}}</dt><dd style="margin: 0">{{sm.value}}</dd></div></sc-for>'
               '<div style="display: flex; justify-content: space-between; padding-top: 6px; border-top: 1px solid #111; font-weight: 700"><dt>{{T.total}}</dt><dd style="margin: 0">{{dc.total}}</dd></div>'
               '<sc-if value="{{dc.hasPaid}}" hint-placeholder-val="{{false}}"><div style="display: flex; justify-content: space-between"><dt>{{T.paid}}</dt><dd style="margin: 0">−{{dc.paidLine}}</dd></div></sc-if>'
               '<sc-if value="{{dc.hasCod}}" hint-placeholder-val="{{true}}"><div style="display: flex; justify-content: space-between; font-weight: 700"><dt>{{T.codDue}}</dt><dd style="margin: 0">{{dc.codDue}}</dd></div></sc-if></dl>'
               '<p style="margin: 40px 0 0; text-align: center; color: #666; font-size: 12px">{{T.thanks}}</p></article>')
    slip = ('<article class="mm-slip"><div style="display: flex; flex-direction: column; gap: 6px"><span style="font-size: 12px; color: #555">{{T.shipTo}}</span><span style="font-size: 22px; line-height: 28px; font-weight: 700">{{dc.name}}</span><span style="font-size: 18px; font-weight: 600">{{dc.phone}}</span><span style="font-size: 16px; line-height: 22px">{{dc.address}}</span></div>'
            '<div style="display: flex; flex-direction: column; align-items: center; gap: 6px">' + qr + '<span style="font-weight: 700; font-size: 16px">{{dc.n}}</span></div>'
            '<div style="grid-column: 1 / -1; padding: 12px 16px; border: 2px solid #111; font-size: 20px; font-weight: 700; text-align: center">{{dc.collect}}</div>'
            '<div style="grid-column: 1 / -1; display: flex; flex-direction: column; gap: 4px"><span style="font-size: 12px; color: #555">{{dc.count}}</span><sc-for list="{{dc.lines}}" as="ln" hint-placeholder-count="2"><span>{{ln.qty}} × {{ln.name}} <span style="color: #666">({{ln.sku}})</span></span></sc-for>'
            '<sc-if value="{{dc.hasNote}}" hint-placeholder-val="{{false}}"><span style="margin-top: 6px; font-weight: 600">{{T.note}}: {{dc.note}}</span></sc-if></div><div style="grid-column: 1 / -1; align-self: end; display: flex; justify-content: space-between; color: #666; font-size: 11px"><span>Nakshi Fashion · 01712-345678</span><span>{{dc.date}}</span></div></article>')
    d = ('<div class="{{themeClass}}" style="min-height: 900px; background: var(--muted); color: var(--foreground); font-family: {{fontStack}}; font-size: 14px; line-height: 20px">'
         '<div class="mm-printbar" role="toolbar" aria-label="Print"><a href="Orders.dc.html" class="mm-btn mm-ghost mm-icon" aria-label="Back to orders">' + svg(ICONS['back']) + '</a><span style="font-weight: 600">{{title}}</span>' + chipsb('docs', 'dd', 2)
         + '<span style="flex: 1"></span><span class="mm-muted" style="font-size: 13px">Print in</span>' + chipsb('langs', 'pl', 2) + '<button type="button" class="mm-btn mm-primary" onClick="{{print}}">' + svg(ICONS['printer']) + 'Print</button></div>'
         '<div style="display: flex; flex-direction: column; align-items: center; gap: 24px; padding: 24px"><sc-for list="{{docsList}}" as="dc" hint-placeholder-count="3"><sc-if value="{{isInvoice}}" hint-placeholder-val="{{true}}">' + invoice + '</sc-if><sc-if value="{{isSlip}}" hint-placeholder-val="{{false}}">' + slip + '</sc-if></sc-for></div>'
         '\n@@DTOAST@@\n</div>\n</x-dc>\n')
    js = mread('print.js').replace("    vals.T = T;", "    vals.T = T;\n    vals.qrc = Array.apply(null, Array(121)).map(function (_, i) { var x = i % 11, y = Math.floor(i / 11); var c = (x < 3 && y < 3) || (x > 7 && y < 3) || (x < 3 && y > 7); return { bg: c ? (x % 10 === 1 && y % 10 === 1 ? '#fff' : '#111') : ((x * 5 + y * 11 + x * y) % 3 === 0 ? '#111' : '#fff') }; });")
    opts = js_starts(js); jsall = RSHARED + sread('shared.js') + js
    write('PrintOrders', auth_head('Print orders'), expand(d), jsall, props(opts, opts[0]), 'mm')
    # Phone: the same documents at phone width, the choices under the header and Print at the bottom.
    pinv = invoice.replace('<article class="mm-paper">', '<article class="mm-paper" style="width: 100%; padding: 20px 18px; font-size: 12px; line-height: 17px">').replace('<div style="display: flex; justify-content: space-between; gap: 24px">', '<div style="display: flex; flex-wrap: wrap; justify-content: space-between; gap: 12px">', 1).replace('width: 300px', 'width: 100%')
    pslip = slip.replace('<article class="mm-slip">', '<article class="mm-slip" style="width: 100%; height: auto; padding: 18px 16px; grid-template-columns: minmax(0, 1fr) 96px; gap: 12px; font-size: 12px; line-height: 17px">').replace('<div class="mm-qr"', '<div class="mm-qr" style="width: 88px; height: 88px; padding: 4px"').replace('font-size: 22px; line-height: 28px', 'font-size: 18px; line-height: 24px').replace('padding: 12px 16px; border: 2px solid #111; font-size: 20px', 'padding: 10px 12px; border: 2px solid #111; font-size: 16px')
    ph = ('<div class="{{themeClass}}" style="position: relative; display: flex; flex-direction: column; width: 390px; height: 844px; overflow: hidden; background: var(--muted); color: var(--foreground); font-family: {{fontStack}}; font-size: 14px; line-height: 20px">'
          + phone_back('OrdersPhone.dc.html', 'Back to orders', '{{title}}')
          + '<div role="toolbar" aria-label="Print" style="flex: none; display: flex; flex-wrap: wrap; align-items: center; gap: 8px 12px; padding: 10px 16px; border-bottom: 1px solid var(--border); background: var(--background)">' + chipsb('docs', 'dd', 2) + '<span style="flex: 1"></span>' + chipsb('langs', 'pl', 2) + '</div>'
          + '<main style="flex: 1; min-height: 0; overflow-y: auto; display: flex; flex-direction: column; gap: 12px; padding: 12px"><sc-for list="{{docsList}}" as="dc" hint-placeholder-count="3"><sc-if value="{{isInvoice}}" hint-placeholder-val="{{true}}">' + pinv + '</sc-if><sc-if value="{{isSlip}}" hint-placeholder-val="{{false}}">' + pslip + '</sc-if></sc-for></main>'
          '<div style="flex: none; display: flex; gap: 8px; padding: 12px 16px; border-top: 1px solid var(--border); background: var(--background)"><button type="button" class="mm-btn mm-primary" style="flex: 1" onClick="{{print}}">' + svg(ICONS['printer']) + 'Print or save as PDF</button></div>\n@@PTOAST0@@\n</div>\n</x-dc>\n')
    write('PrintOrdersPhone', auth_phone_head('Print orders'), expand(ph, True), jsall, props(opts, opts[0], True), 'mm')

def poprint():
    paper = ('<article class="mm-paper" style="%s"><div style="display: flex; justify-content: space-between; gap: 20px; flex-wrap: wrap"><div><span style="font-size: 20px; font-weight: 700">{{po.title}}</span><p style="margin: 4px 0 0">Date: {{po.date}} · Expected on: {{po.expected}}</p><p style="margin: 0; color: #555">Supplier’s reference: {{po.supRef}}</p></div></div>'
             '<div style="display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; margin: 24px 0"><div><p style="margin: 0 0 4px; font-weight: 600">From</p><p style="margin: 0">Nakshi Fashion House</p><p style="margin: 0; color: #444">House 18, Road 7, Block C, Mirpur 10, Dhaka · 01712-345678</p></div>'
             '<div><p style="margin: 0 0 4px; font-weight: 600">To</p><p style="margin: 0">{{po.supplier}}</p><p style="margin: 0; color: #444">{{po.supContact}}</p><p style="margin: 0; color: #444">{{po.supAddr}}</p></div></div>'
             '<table><thead><tr><th>Items</th><th class="r">Ordered</th><th class="r">Cost each</th><th class="r">Total</th></tr></thead><tbody><sc-for list="{{po.lines}}" as="pl2" hint-placeholder-count="2"><tr><td>{{pl2.name}}<br><span style="color: #666; font-size: 11px">{{pl2.sku}}</span></td><td class="r">{{pl2.qty}}</td><td class="r">{{pl2.cost}}</td><td class="r">{{pl2.total}}</td></tr></sc-for></tbody></table>'
             '<dl style="margin: 16px 0 0 auto; width: 280px; max-width: 100%%; display: flex; flex-direction: column; gap: 4px"><div style="display: flex; justify-content: space-between"><dt>Goods</dt><dd style="margin: 0">{{po.goods}}</dd></div><sc-for list="{{po.costs}}" as="pc" hint-placeholder-count="1"><div style="display: flex; justify-content: space-between"><dt>{{pc.label}}</dt><dd style="margin: 0">{{pc.value}}</dd></div></sc-for>'
             '<div style="display: flex; justify-content: space-between; padding-top: 6px; border-top: 1px solid #111; font-weight: 700"><dt>Total</dt><dd style="margin: 0">{{po.total}}</dd></div></dl></article>')
    bar_html = ('<div class="mm-printbar" role="toolbar" aria-label="Print"><a href="%s" class="mm-btn mm-ghost mm-icon" aria-label="Back to the purchase order">' + svg(ICONS['back']) + '</a><span style="font-weight: 600">{{po.title}}</span><span style="flex: 1"></span>'
                '<button type="button" class="mm-btn mm-outline" onClick="{{share}}">' + svg(ICONS['msg']) + 'Share on WhatsApp</button><button type="button" class="mm-btn mm-primary" onClick="{{print}}">' + svg(ICONS['printer']) + 'Print or save as PDF</button></div>')
    d = ('<div class="{{themeClass}}" style="min-height: 900px; background: var(--muted); color: var(--foreground); font-family: {{fontStack}}; font-size: 14px; line-height: 20px">' + bar_html % 'PurchaseOrder.dc.html'
         + '<div style="display: flex; justify-content: center; padding: 24px">' + paper % '' + '</div>\n@@DTOAST@@\n</div>\n</x-dc>\n')
    pbar_html = ('<div style="display: flex; align-items: center; gap: 4px; height: 56px; padding: 0 8px; border-bottom: 1px solid var(--border); background: var(--background)"><a href="PurchaseOrderPhone.dc.html" class="mm-btn mm-ghost mm-icon" aria-label="Back to the purchase order">' + svg(ICONS['back'], 20) + '</a><h1 class="mm-trunc" style="flex: 1; margin: 0 4px; font-size: 16px; font-weight: 600">{{po.title}}</h1></div>')
    ph = ('<div class="{{themeClass}}" style="position: relative; display: flex; flex-direction: column; width: 390px; height: 844px; overflow: hidden; background: var(--muted); color: var(--foreground); font-family: {{fontStack}}; font-size: 14px; line-height: 20px">' + pbar_html
          + '<main style="flex: 1; min-height: 0; overflow-y: auto; padding: 12px">' + (paper % 'width: 100%; padding: 20px 18px; font-size: 12px').replace('repeat(2, minmax(0, 1fr))', 'minmax(0, 1fr)') + '</main>'
          '<div style="flex: none; display: flex; gap: 8px; padding: 12px 16px; border-top: 1px solid var(--border); background: var(--background)"><button type="button" class="mm-btn mm-outline" style="flex: 1" onClick="{{print}}">' + svg(ICONS['printer']) + 'PDF</button><button type="button" class="mm-btn mm-primary" style="flex: 2" onClick="{{share}}">' + svg(ICONS['msg']) + 'Share on WhatsApp</button></div>\n@@PTOAST0@@\n</div>\n</x-dc>\n')
    js = mread('poprint.js'); opts = js_starts(js); jsall = RSHARED + sread('shared.js') + js
    write('PrintPurchaseOrder', auth_head('Purchase order'), expand(d), jsall, props(opts, opts[0]), 'mm')
    write('PrintPurchaseOrderPhone', auth_phone_head('Purchase order'), expand(ph, True), jsall, props(opts, opts[0], True), 'mm')

